package configs_test

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

const (
	migrationDatabaseKey = "MIGRATION_DATABASE_URL"
	databaseKey          = "DATABASE_URL"
	dotEnvDatabase       = "postgres://dummy/dotenv"
	exportedDatabase     = "postgres://dummy/exported"
	explicitDatabase     = "postgres://dummy/explicit"
)

// Generated by Codex and not thoroughly checked for correctness.
func TestMigrationEnvironmentPrecedence(t *testing.T) {
	makefile, err := filepath.Abs("../../../Makefile")
	if err != nil {
		t.Fatal(err)
	}
	for _, testCase := range []struct {
		name        string
		dotEnv      string
		environment map[string]string
		arguments   []string
		wantURL     string
		wantError   bool
	}{
		{name: "dotenv supplies an unset database", dotEnv: databaseKey + "=" + dotEnvDatabase, wantURL: dotEnvDatabase},
		{name: "exported database wins over dotenv", dotEnv: databaseKey + "=" + dotEnvDatabase, environment: map[string]string{databaseKey: exportedDatabase}, wantURL: exportedDatabase},
		{name: "exported migration target wins over both dotenv targets", dotEnv: databaseKey + "=" + dotEnvDatabase + "\n" + migrationDatabaseKey + "=" + dotEnvDatabase, environment: map[string]string{databaseKey: exportedDatabase, migrationDatabaseKey: explicitDatabase}, wantURL: explicitDatabase},
		{name: "dedicated dotenv migration target precedes database fallback", dotEnv: migrationDatabaseKey + "=" + dotEnvDatabase, environment: map[string]string{databaseKey: exportedDatabase}, wantURL: dotEnvDatabase},
		{name: "command line database wins over environment and dotenv", dotEnv: databaseKey + "=" + dotEnvDatabase, environment: map[string]string{databaseKey: exportedDatabase}, arguments: []string{databaseKey + "=" + explicitDatabase}, wantURL: explicitDatabase},
		{name: "command line migration target wins over environment and dotenv", dotEnv: migrationDatabaseKey + "=" + dotEnvDatabase, environment: map[string]string{migrationDatabaseKey: exportedDatabase}, arguments: []string{migrationDatabaseKey + "=" + explicitDatabase}, wantURL: explicitDatabase},
		{name: "empty exported database is not replaced by dotenv", dotEnv: databaseKey + "=" + dotEnvDatabase, environment: map[string]string{databaseKey: ""}, wantError: true},
		{name: "empty exported migration target is not replaced by dotenv", dotEnv: migrationDatabaseKey + "=" + dotEnvDatabase, environment: map[string]string{migrationDatabaseKey: ""}, wantError: true},
		{name: "literal characters in exported URL survive inclusion", dotEnv: databaseKey + "=" + dotEnvDatabase, environment: map[string]string{databaseKey: "postgres://dummy/p$ss#word?application_name=two words"}, wantURL: "postgres://dummy/p$ss#word?application_name=two words"},
		{name: "exported target works without dotenv", environment: map[string]string{databaseKey: exportedDatabase}, wantURL: exportedDatabase},
		{name: "missing database fails before migration", wantError: true},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			directory := t.TempDir()
			if testCase.dotEnv != "" {
				if err := os.WriteFile(filepath.Join(directory, ".env"), []byte(testCase.dotEnv+"\n"), 0600); err != nil {
					t.Fatal(err)
				}
			}
			// Exercise the real target, replacing only the database command.
			mockMigration := `#!/bin/sh
if [ "${dotenv_original_DATABASE_URL+x}" = x ] || [ "${dotenv_original_MIGRATION_DATABASE_URL+x}" = x ]; then
	printf 'temporary environment copies were exported' >&2
	exit 1
fi
printf '%s' "$4"
`
			if err := os.WriteFile(filepath.Join(directory, "mock-migration.sh"), []byte(mockMigration), 0700); err != nil {
				t.Fatal(err)
			}
			arguments := append([]string{"--no-print-directory", "-f", makefile, "migrate-version", "MIGRATE=sh ./mock-migration.sh"}, testCase.arguments...)
			command := exec.CommandContext(t.Context(), "make", arguments...)
			command.Dir = directory
			for _, entry := range os.Environ() {
				key, _, _ := strings.Cut(entry, "=")
				switch key {
				case databaseKey, migrationDatabaseKey, "MAKEFLAGS", "MFLAGS", "MAKEOVERRIDES":
					continue
				}
				command.Env = append(command.Env, entry)
			}
			for key, value := range testCase.environment {
				command.Env = append(command.Env, key+"="+value)
			}
			output, err := command.CombinedOutput()
			if testCase.wantError {
				if err == nil || !strings.Contains(string(output), "DATABASE_URL or MIGRATION_DATABASE_URL is required") {
					t.Fatalf("make error = %v, output = %q; want missing database error", err, output)
				}
				return
			}
			if err != nil || string(output) != testCase.wantURL {
				t.Fatalf("make target = %q, error = %v; want %q", output, err, testCase.wantURL)
			}
		})
	}
}
